import{_ as d,C as e,o as l,c as n,j as t,E as o,a as r,a3 as s}from"./chunks/framework.C6R8kWFE.js";const q=JSON.parse(`{"title":"4-hafta (Mentor)","description":"","frontmatter":{"title":"4-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"11-sinf","link":"/mentor/11-sinf/"},"n":4,"bob":"I-bob · Dasturiy ta'minot ishlab chiqish asoslari","lessons":[{"g":10,"title":"Loyihalash andozalari: Observer va hodisalar arxitekturasi","lead":"Bitta voqea, ko'p javob beruvchi: Observer yordamida «buyurtma yakunlandi» signalini kuzatuvchilarga tarqatamiz va kod bir-biriga bog'lanib qolishining oldini olamiz.","link":"/mentor/11-sinf/hafta-04/dars-1","slide":"/slaydlar/11-sinf/hafta-04/dars-1.html","test":"/slaydlar/11-sinf/hafta-04/dars-1-test.html"},{"g":11,"title":"REST API va JSON asoslari: REST tamoyillari va HTTP","lead":"Har bir ilova serverdan ma'lumotni bir xil tilda so'raydi: HTTP. Bugun kutubxona uchun o'z REST API'ngizni yozib, curl bilan chaqirasiz.","link":"/mentor/11-sinf/hafta-04/dars-2","slide":"/slaydlar/11-sinf/hafta-04/dars-2.html","test":"/slaydlar/11-sinf/hafta-04/dars-2-test.html"},{"g":12,"title":"REST API va JSON asoslari: JSON formati, kontrakt va xavfsizlik","lead":"API ning yuragi: JSON kontrakti. Maydonlar nomi, xato formati va xavfsizlik qoidalari bo'yicha mijoz va server o'rtasida «kelishuv» tuzamiz.","link":"/mentor/11-sinf/hafta-04/dars-3","slide":"/slaydlar/11-sinf/hafta-04/dars-3.html","test":"/slaydlar/11-sinf/hafta-04/dars-3-test.html"}],"test":"/slaydlar/11-sinf/hafta-04/hafta-test.html"}},"headers":[],"relativePath":"mentor/11-sinf/hafta-04/index.md","filePath":"mentor/11-sinf/hafta-04/index.md"}`),h={name:"mentor/11-sinf/hafta-04/index.md"},u={class:"blk"},c={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},v={class:"blk"},b={id:"baholash-mezoni",tabindex:"-1"};function m(_,a,g,k,y,f){const i=e("Icon");return l(),n("div",null,[t("div",u,[t("h2",c,[o(i,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=s('<p>Har bir vazifa 20–30 daqiqa. Parol, shaxsiy token, maxfiy kalit va shaxsiy ma&#39;lumotlarni repozitoriyga yozmang: topshirishda faqat ochiq GitHub repo yoki Pull Request havolasi kerak.</p><h2 id="_10-dars-uchun-observer-va-eventbus" tabindex="-1">10-dars uchun (Observer va EventBus) <a class="header-anchor" href="#_10-dars-uchun-observer-va-eventbus" aria-label="Permalink to &quot;10-dars uchun (Observer va EventBus)&quot;">​</a></h2><p><strong>1-topshiriq: «Kutubxona EventBus tizimi»</strong></p><ol><li>O&#39;z GitHub portfolio repozitoriyangizda <code>feature/observer-eventbus</code> tarmog&#39;ini oching.</li><li><code>library_events.py</code> faylida markaziy <code>EventBus</code> sinfini e&#39;lon qiling (<code>subscribe</code>, <code>unsubscribe</code>, <code>publish</code>).</li><li><code>book:borrowed</code> hodisasi uchun ikkita kuzatuvchi yarating: <ul><li><code>AuditLogger</code> — berilgan kitob va o&#39;quvchi ma&#39;lumotlarini <code>logs/library.log</code> fayliga qo&#39;shadi;</li><li><code>StudentNotifier</code> — qaytarish muddatini hisoblab terminalga xabar chiqaradi.</li></ul></li><li><code>test_events.py</code> faylida <code>unittest.mock.MagicMock</code> yordamida <code>publish</code> chaqirilganda barcha kuzatuvchilar ishga tushishini tekshiruvchi 2 ta unit test yozing.</li><li>Semantik commitlar bilan GitHub&#39;ga yuboring.</li></ol><p><strong>Kutiladigan natija:</strong> bo&#39;sh bog&#39;langan, OCP talablariga mos, testlangan EventBus kodi.<br><strong>Topshirish:</strong> GitHub commit yoki fayl havolasi.</p><hr><h2 id="_11-dars-uchun-rest-tamoyillari-va-http-metodlari" tabindex="-1">11-dars uchun (REST tamoyillari va HTTP metodlari) <a class="header-anchor" href="#_11-dars-uchun-rest-tamoyillari-va-http-metodlari" aria-label="Permalink to &quot;11-dars uchun (REST tamoyillari va HTTP metodlari)&quot;">​</a></h2><p><strong>2-topshiriq: «REST API URI loyihasi va curl sinovlari»</strong></p><ol><li><code>docs/api_design.md</code> faylida «Kutubxona boshqaruvi» tizimi uchun RESTful endpointlar jadvalini tuzing: <ul><li>Kitoblarni olish (<code>GET /api/v1/books</code>), yangi kitob qo&#39;shish (<code>POST</code>), ID bo&#39;yicha olish (<code>GET /api/v1/books/{id}</code>), o&#39;chirish (<code>DELETE</code>);</li><li>Ko&#39;plik otlar, ierarxiya va to&#39;g&#39;ri HTTP metodlari qo&#39;llansin.</li></ul></li><li>Har bir amal uchun qaytishi kerak bo&#39;lgan kutilayotgan HTTP status kodlarini (200, 201, 204, 400, 404) yozing.</li><li><code>test_api.sh</code> nomli skript fayl tuzib, unga ushbu endpointlarni sinovdan o&#39;tkazuvchi kamida 4 ta <code>curl</code> buyrug&#39;ini yozing (<code>-X</code>, <code>-H &quot;Content-Type: application/json&quot;</code>, <code>-d</code>, <code>-v</code> bayroqlari bilan).</li></ol><p><strong>Kutiladigan natija:</strong> to&#39;g&#39;ri loyihalangan RESTful URI hujjati va terminalda ishlovchi curl sinov skripti.<br><strong>Topshirish:</strong> <code>docs/api_design.md</code> va <code>test_api.sh</code> havolasi.</p><hr><h2 id="_12-dars-uchun-json-formati-kontrakt-va-xavfsizlik" tabindex="-1">12-dars uchun (JSON formati, Kontrakt va Xavfsizlik) <a class="header-anchor" href="#_12-dars-uchun-json-formati-kontrakt-va-xavfsizlik" aria-label="Permalink to &quot;12-dars uchun (JSON formati, Kontrakt va Xavfsizlik)&quot;">​</a></h2><p><strong>3-topshiriq: «JSON Kontrakt, Error Envelope va DTO xavfsizligi»</strong></p><ol><li><code>contracts.py</code> faylida quyidagi qoidalarga mos keluvchi JSON serializatsiya funksiyalarini yozing: <ul><li>Yagona xatolik formati (<code>Error Envelope</code>): <code>{&quot;error&quot;: {&quot;code&quot;: &quot;...&quot;, &quot;message&quot;: &quot;...&quot;, &quot;details&quot;: [...]}}</code> qaytaruvchi <code>make_error_response()</code> funksiyasi;</li><li>Paginatsiya javobini shakllantiruvchi <code>make_paginated_response(data, limit, offset, total)</code> funksiyasi (<code>data</code> va <code>meta</code> bo&#39;limlari bilan);</li><li>Xavfsiz DTO filtri: Foydalanuvchi obyektidan <code>password_hash</code>, <code>token</code>, <code>secret_key</code> maydonlarini olib tashlab, sanalarni ISO-8601 UTC formatiga o&#39;tkazuvchi <code>sanitize_user()</code> funksiyasi.</li></ul></li><li><code>test_contracts.py</code> faylida har uchala funksiyani <code>pytest</code> yoki <code>assert</code> bilan tekshiruvchi testlar yozing.</li><li>Barcha ishlarni <code>main</code> tarmog&#39;iga Pull Request qilib yuboring.</li></ol><p><strong>Kutiladigan natija:</strong> xalqaro standartlarga mos, xavfsiz JSON kontrakt moduli va yashil unit testlar.<br><strong>Topshirish:</strong> GitHub Pull Request havolasi.</p><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p>Dars boshida 10-dars bo&#39;yicha kuzatuvchilardan biri xato bersa boshqalari to&#39;xtab qolmasligi tekshirilganini ko&#39;ring (<code>try/except</code> mavjudligi). 11-darsda URI ichida fe&#39;llar (<code>/getBooks</code>, <code>/delete_book</code>) ishlatilmaganiga, resurslar ko&#39;plikda nomlanganiga ishonch hosil qiling. 12-darsda <code>sanitize_user</code> funksiyasida <code>password_hash</code> mijozga chiqib ketmasligi va xato javoblarida yagona <code>error</code> kaliti ishlatilganini tahlil qiling.</p>',18))]),t("div",v,[t("h2",b,[o(i,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=s('<p>Bitta o&#39;quvchi uchun shablon. Maqsad: haftalar bo&#39;yicha o&#39;sish dinamikasini kuzatish. Har hafta shu shablon nusxalanib, «Dinamika» jadvaliga bitta qator qo&#39;shiladi.</p><p><strong>O&#39;quvchi:</strong> ____________________ <strong>Guruh/sinf:</strong> 11-sinf <strong>Mentor:</strong> ____________________</p><h2 id="shkala-va-mezonlar-o-quv-dasturi-8-bo-lim" tabindex="-1">Shkala va mezonlar (o&#39;quv dasturi, 8-bo&#39;lim) <a class="header-anchor" href="#shkala-va-mezonlar-o-quv-dasturi-8-bo-lim" aria-label="Permalink to &quot;Shkala va mezonlar (o&#39;quv dasturi, 8-bo&#39;lim)&quot;">​</a></h2><p>100 ballik shkala: <strong>90–100 — 5 (a&#39;lo)</strong>, <strong>71–89 — 4 (yaxshi)</strong>, <strong>60–70 — 3 (qoniqarli)</strong>, <strong>0–59 — 2 (qoniqarsiz)</strong>.</p><p>Dasturdagi mezonlar: mavzu bo&#39;yicha tasavvurga ega bo&#39;lish; mavzu mohiyatini tushunish va aytib bera olish; bilimni amalda qo&#39;llash; ijodiy fikrlash va xulosa chiqarish; mustaqil ish bajarish.</p><table tabindex="0"><thead><tr><th>Mezon</th><th>Max</th></tr></thead><tbody><tr><td>Mohiyatni tushunadi va aytib bera oladi (tezkor nazorat, og&#39;zaki)</td><td>30</td></tr><tr><td>Amaliy topshiriq: to&#39;g&#39;ri va to&#39;liq, mustaqil bajarilgan</td><td>30</td></tr><tr><td>Ish sifati: toza arxitektura, REST/JSON standartlari, xavfsizlik, testlar</td><td>20</td></tr><tr><td>Uyga vazifa bajarilgan va o&#39;z vaqtida topshirilgan</td><td>20</td></tr><tr><td><strong>Jami</strong></td><td><strong>100</strong></td></tr></tbody></table><hr><h2 id="_10-dars-loyihalash-andozalari-observer-va-hodisalar-arxitekturasi" tabindex="-1">10-dars. Loyihalash andozalari: Observer va hodisalar arxitekturasi <a class="header-anchor" href="#_10-dars-loyihalash-andozalari-observer-va-hodisalar-arxitekturasi" aria-label="Permalink to &quot;10-dars. Loyihalash andozalari: Observer va hodisalar arxitekturasi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>Subject/Observer rollari; publish/subscribe va loose coupling mohiyati; memory leak xatarlari</td><td></td></tr><tr><td>Amaliyot /30</td><td><code>EventBus</code> sinfini qurish; bir nechta kuzatuvchini ro&#39;yxatdan o&#39;tkazish va xabardor qilish</td><td></td></tr><tr><td>Ish sifati /20</td><td><code>try/except</code> orqali xatolarni izolyatsiya qilish; <code>MagicMock</code> bilan to&#39;liq unit testlar yozilgani</td><td></td></tr><tr><td>Uyga vazifa /20</td><td><code>library_events.py</code> va <code>test_events.py</code> topshirilgan; Git commitlar to&#39;g&#39;ri formatlangan</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><hr><h2 id="_11-dars-rest-api-va-json-asoslari-rest-tamoyillari-va-http" tabindex="-1">11-dars. REST API va JSON asoslari: REST tamoyillari va HTTP <a class="header-anchor" href="#_11-dars-rest-api-va-json-asoslari-rest-tamoyillari-va-http" aria-label="Permalink to &quot;11-dars. REST API va JSON asoslari: REST tamoyillari va HTTP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>REST 5 ustuni; URI dizayni (ot + ko&#39;plik); HTTP metodlari semantikasi va idempotentlik</td><td></td></tr><tr><td>Amaliyot /30</td><td>Resurslar ierarxiyasini loyihalash; 2xx/4xx/5xx status kodlarini to&#39;g&#39;ri tanlash</td><td></td></tr><tr><td>Ish sifati /20</td><td><code>curl</code> buyruqlari sarlavhalar (<code>Content-Type</code>, <code>Accept</code>) va tana (<code>-d</code>) bilan to&#39;g&#39;ri ishlatilgani</td><td></td></tr><tr><td>Uyga vazifa /20</td><td><code>docs/api_design.md</code> va <code>test_api.sh</code> sinov skripti to&#39;liq tayyorlangan</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><hr><h2 id="_12-dars-rest-api-va-json-asoslari-json-formati-kontrakt-va-xavfsizlik" tabindex="-1">12-dars. REST API va JSON asoslari: JSON formati, kontrakt va xavfsizlik <a class="header-anchor" href="#_12-dars-rest-api-va-json-asoslari-json-formati-kontrakt-va-xavfsizlik" aria-label="Permalink to &quot;12-dars. REST API va JSON asoslari: JSON formati, kontrakt va xavfsizlik&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>JSON 6 turi; ISO-8601 UTC vaqti; 401 vs 403 farqi; CORS va Rate Limit (429) tushunchalari</td><td></td></tr><tr><td>Amaliyot /30</td><td>Yagona Error Envelope va Paginatsiya tuzilmasini yaratish; DTO bilan xavfli maydonlarni yashirish</td><td></td></tr><tr><td>Ish sifati /20</td><td>Xavfsizlik intizomi (<code>password_hash</code> chiqib ketmasligi); <code>test_contracts.py</code> yashil o&#39;tgani</td><td></td></tr><tr><td>Uyga vazifa /20</td><td><code>contracts.py</code> to&#39;liq yozilgan, barcha testlar muvaffaqiyatli, GitHub PR topshirilgan</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><hr><h2 id="_4-hafta-yakuni-o-sish-dinamikasi" tabindex="-1">4-hafta yakuni: o&#39;sish dinamikasi <a class="header-anchor" href="#_4-hafta-yakuni-o-sish-dinamikasi" aria-label="Permalink to &quot;4-hafta yakuni: o&#39;sish dinamikasi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hafta</th><th>Darslar</th><th>O&#39;rtacha ball</th><th>Baho</th><th>Asosiy yutuq / Aniqlangan bo&#39;shliq</th></tr></thead><tbody><tr><td>1-hafta</td><td>1–3 (SDLC, Git)</td><td></td><td></td><td></td></tr><tr><td>2-hafta</td><td>4–6 (Branching, PR)</td><td></td><td></td><td></td></tr><tr><td>3-hafta</td><td>7–9 (SOLID, Patterns)</td><td></td><td></td><td></td></tr><tr><td>4-hafta</td><td>10–12 (Observer, REST, JSON)</td><td></td><td></td><td></td></tr></tbody></table><p><strong>Mentor tavsiyasi:</strong> O&#39;quvchi I-bobning texnik qismini (Clean Code, SOLID, Creational &amp; Behavioral Patternlar, REST API va JSON kontrakt dizayni) to&#39;liq yakunladi. 5-haftada I-bobning yakuniy soft skills mavzulari (muloqot, liderlik, vaqt boshqaruvi) hamda <strong>Oraliq nazorat (15-dars)</strong> o&#39;tkaziladi.</p>',22))])])}const z=d(h,[["render",m]]);export{q as __pageData,z as default};
